<script setup>
import {ref,onMounted,onUnmounted} from 'vue';
const emit=defineEmits(['close']);const panel=ref(null);let previousFocus;
function key(event){if(event.key==='Escape'){emit('close');return;}if(event.key!=='Tab')return;const items=[...panel.value.querySelectorAll('button,a[href]')];const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
onMounted(()=>{previousFocus=document.activeElement;panel.value.querySelector('button').focus();document.addEventListener('keydown',key);});onUnmounted(()=>{document.removeEventListener('keydown',key);previousFocus?.focus();});
</script>
<template><div class="modal-backdrop" @click.self="$emit('close')"><section ref="panel" class="support-panel card" role="dialog" aria-modal="true" aria-labelledby="support-title"><div class="section-top"><span class="eyebrow">Within reach</span><button class="text-button" @click="$emit('close')">Close support</button></div><h2 id="support-title">Support, whenever you need it.</h2><p>This prototype is not monitored. No one is watching this chat or responding to your exercise activity.</p><p>In the United States and its territories, the 988 Suicide &amp; Crisis Lifeline offers support.</p><div class="support-links"><a class="primary" href="tel:988?oai_link_source=model_response_hotline">Call 988</a><a class="secondary" href="sms:988?oai_link_source=model_response_hotline">Text 988</a><a class="secondary" href="https://988lifeline.org/chat/?oai_link_source=model_response_hotline" target="_blank" rel="noopener">Chat with 988 ↗</a></div><p class="fine">If you are in immediate danger, contact local emergency services. Outside the US, use your local emergency or crisis-support resources.</p><a href="https://988lifeline.org?oai_link_source=model_response_hotline" target="_blank" rel="noopener">About the Lifeline ↗</a></section></div></template>
